import{_ as a,o as r,c as o,ag as t}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"🔬 科学快报 | 2026年8月17日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-17.md","filePath":"science-log/src/reconstructed/2026-08-17.md"}'),n={name:"science-log/src/reconstructed/2026-08-17.md"};function i(s,e,l,h,c,d){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="🔬-科学快报-2026年8月17日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月17日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月17日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月17日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608170000 TO 202608172359]</code>（cs.AI，命中 30 篇）｜ 重建日：2026-11-05 说明：2026-08-17 为<strong>周一</strong>，Nature 当日 <code>10.1038/s41586-…</code> 命中 3 篇研究论文（另 1 条为 Author Correction，已剔除）；Science 系当日命中 4 条但全为新闻/政策稿，不含研究论文；PNAS 当日命中 15 条。故科学 5 篇 = Nature 2 + PNAS 3。期号不可考，故记为 <code>第 ? 期</code>。</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="☀️-三结钙钛矿-钙钛矿-硅电池认证效率-32-22-宽带隙子电池开路电压-1-413-v" tabindex="-1">☀️ 三结钙钛矿/钙钛矿/硅电池认证效率 32.22%，宽带隙子电池开路电压 1.413 V <a class="header-anchor" href="#☀️-三结钙钛矿-钙钛矿-硅电池认证效率-32-22-宽带隙子电池开路电压-1-413-v" aria-label="Permalink to &quot;☀️ 三结钙钛矿/钙钛矿/硅电池认证效率 32.22%，宽带隙子电池开路电压 1.413 V&quot;">​</a></h3><p><strong>Defect passivation and optical management of triple-junction solar cells</strong><em>Nature (2026)</em></p><p>三结「钙钛矿/钙钛矿/硅」叠层是低成本突破单结 Shockley–Queisser 极限的主路线，但受限于宽带隙钙钛矿的非辐射复合损失与多层堆叠的光管理不佳。作者设计钝化分子 4F-POEABr（2,2&#39;-((全氟-1,4-苯撑)双(氧))双乙胺二溴盐），其「铵基 + 缺电子」结构同时提供化学钝化与场效应钝化，把宽带隙子电池的准费米能级分裂提升到 1.53 eV、开路电压达 1.413 V。再用锡氧化物/铟锌氧化物双层做系统性的干涉管理，优化作为电流限制层的中间子电池，电流密度增益 0.5 mA cm⁻²。器件获认证稳态效率 32.22%（1.046 cm²）与 26.97%（15.62 cm²），滞后可忽略，互连层与界面工程同时改善运行稳定性。DOI: <a href="https://doi.org/10.1038/s41586-026-11010-8" target="_blank" rel="noreferrer">10.1038/s41586-026-11010-8</a></p><h3 id="⚗️-让吡啶环里的氮原子「换位」-位置异构体可直接互变" tabindex="-1">⚗️ 让吡啶环里的氮原子「换位」：位置异构体可直接互变 <a class="header-anchor" href="#⚗️-让吡啶环里的氮原子「换位」-位置异构体可直接互变" aria-label="Permalink to &quot;⚗️ 让吡啶环里的氮原子「换位」：位置异构体可直接互变&quot;">​</a></h3><p><strong>Positional isomerization of pyridine through nitrogen transposition</strong><em>Nature (2026)</em></p><p>吡啶的位置异构体（2-/3-/4-取代）生物活性往往截然不同，但彼此无法直接转化，只能各自独立合成。首尔大学 Sungwoo Hong 团队报告了一种通过杂芳环骨架受控重组实现吡啶位置异构化的通用策略：以「顺序插入氮 + 删除氮」完成氮原子换位，从而可预测地搬移已装上的取代基，而不改变取代基本身。方法适用于单取代、双取代与多取代吡啶，也能在结构复杂的分子环境中运行，直接给出目标位置异构体。这把「吡啶取代模式」从固定的合成起点变成了逆合成设计中可变的变量。DOI: <a href="https://doi.org/10.1038/s41586-026-11006-4" target="_blank" rel="noreferrer">10.1038/s41586-026-11006-4</a></p><h3 id="🌍-印度-singhbhum-克拉通-35-亿年前微生物席残体中的生物碳被直接定年" tabindex="-1">🌍 印度 Singhbhum 克拉通 35 亿年前微生物席残体中的生物碳被直接定年 <a class="header-anchor" href="#🌍-印度-singhbhum-克拉通-35-亿年前微生物席残体中的生物碳被直接定年" aria-label="Permalink to &quot;🌍 印度 Singhbhum 克拉通 35 亿年前微生物席残体中的生物碳被直接定年&quot;">​</a></h3><p><strong>Direct dating of 3.5 Ga biogenic carbon in a microbial mat remnant, Singhbhum Craton, India</strong><em>PNAS (2026)</em></p><p>早期生命证据的最大软肋是「碳是生物的」与「岩石年龄」两件事往往分别论证、彼此脱钩。作者在印度东部铁矿带 Bhitardari 燧石（低绿片岩相「黑白条带」）中取出被视为同火山成因的锆石，给出 ²⁰⁷Pb/²⁰⁶Pb 年龄 3497 ± 5 Ma（n = 4，MSWD = 1.2），把含碳岩石本身钉在古太古代。该燧石富含碳质物，呈两种结构：基质内超细纹层与晚期石英脉中的石墨鳞片，两种模式的 bulk δ¹³C 均为 −30.9‰，被解释为生物成因。这是「直接定年 + 含碳质物 + 具生物学诊断性碳同位素」三者同一样品闭合的首批记录之一，且该值符合 3.5 Ga 前已出现较复杂代谢（如 Calvin 循环）的推断。DOI: <a href="https://doi.org/10.1073/pnas.2617912123" target="_blank" rel="noreferrer">10.1073/pnas.2617912123</a></p><h3 id="🪐-金属与硅酸盐互溶-→-可存在「无核」系外行星" tabindex="-1">🪐 金属与硅酸盐互溶 → 可存在「无核」系外行星 <a class="header-anchor" href="#🪐-金属与硅酸盐互溶-→-可存在「无核」系外行星" aria-label="Permalink to &quot;🪐 金属与硅酸盐互溶 → 可存在「无核」系外行星&quot;">​</a></h3><p><strong>Coreless exoplanets induced by metal–silicate miscibility</strong><em>PNAS (2026)</em></p><p>岩石行星通常分异为硅酸盐地幔与金属核，前提是二者在行星形成条件下不互溶。作者用机器学习势（ab initio 精度）驱动的大规模分子动力学，扫描系外行星内部极端压强—温度下金属液体与硅酸盐熔体的相行为，给出「溶线闭合曲线（solvus closure curve）」：在此之上，铁—硅酸盐混合物以单一均相液体稳定存在。按地球整体成分与内部模型推断，该曲线允许部分混合甚至完全混合的内部，出现在一些带厚气包层的热超级地球与亚海王星上。与已分异行星相比，无核行星的质量—半径关系几乎相同，但内部压缩明显更小，中心压强最多降低一倍；其流体 Love 数更大，是未来任务可以观测检验的量。DOI: <a href="https://doi.org/10.1073/pnas.2615884123" target="_blank" rel="noreferrer">10.1073/pnas.2615884123</a></p><h3 id="🦴-两具尼安德特人骨盆-分娩机制与人相似-权衡在骨盆底而非行走" tabindex="-1">🦴 两具尼安德特人骨盆：分娩机制与人相似，权衡在骨盆底而非行走 <a class="header-anchor" href="#🦴-两具尼安德特人骨盆-分娩机制与人相似-权衡在骨盆底而非行走" aria-label="Permalink to &quot;🦴 两具尼安德特人骨盆：分娩机制与人相似，权衡在骨盆底而非行走&quot;">​</a></h3><p><strong>Insights into Neanderthal development, childbirth, and locomotion from the Palomas and Dederiyeh pelves</strong><em>PNAS (2026)</em></p><p>人类骨盆是分娩、双足行走、骨盆底稳定与体温调节之间的演化折中，但化石稀少使尼安德特人的取舍长期不明。作者对西班牙 Sima de las Palomas del Cabezo Gordo 与叙利亚 Dederiyeh 洞近完整的尼安德特人骨盆做新的虚拟重建与形态测量，并与其它尼安德特人及现代人对比。结果显示：尼安德特人与现代人的骨盆整体形状自幼年即不同，但两性异形模式相似；与分娩相关的骨盆区域功能形态可比，提示产道机制类似；而与行走相关的特征（髋关节朝向、肌肉力臂几何）不同，说明站姿与步态适应有别。这支持把经典「产科困境」重述为「分娩 vs 骨盆底稳定性」的权衡，而非「分娩 vs 运动性能」。DOI: <a href="https://doi.org/10.1073/pnas.2535303123" target="_blank" rel="noreferrer">10.1073/pnas.2535303123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🤖-teach-and-grow-免训练的「技能块-经验记忆」架构-libero-四套件-99-9" tabindex="-1">🤖 Teach and Grow：免训练的「技能块 + 经验记忆」架构，LIBERO 四套件 99.9% <a class="header-anchor" href="#🤖-teach-and-grow-免训练的「技能块-经验记忆」架构-libero-四套件-99-9" aria-label="Permalink to &quot;🤖 Teach and Grow：免训练的「技能块 + 经验记忆」架构，LIBERO 四套件 99.9%&quot;">​</a></h3><p><strong>Teach and Grow: An Agent-Centered Architecture for General Robot Learning</strong><em>arXiv (2026)</em></p><p>VLA 与世界动作模型通常要靠补采机器人数据 + 策略优化才能吸收新操作任务，这个反复重训的负担拖慢了新行为的获得。作者提出 Teach-and-Grow Learning（TGL）：完全免训练，把少量成功演示转成可复用技能，预训练权重全程冻结、不梯度更新、不微调、不 RL。智能体（GPT-6 Astra 做多模态推理，Codex 连接机器人工具）从演示中识别共享子目标，写成闭环的 Skill Block 并在当前场景中落地，物理反馈驱动下一步与恢复；验证过的行为进入持久 Skill Library，Experience Memory 记录条件与修复方式。实测四套 LIBERO 平均成功率 99.9%，七类 LIBERO-Plus 扰动 92.4%；演示只是「加速器」而非前提，因为智能体也能直接驱动机器人。arXiv: <a href="https://arxiv.org/abs/2608.17209" target="_blank" rel="noreferrer">2608.17209</a></p><h3 id="🛡️-fool-s-gold-防不住就去骗——对抗「安全移除」的开源权重诱饵加固" tabindex="-1">🛡️ Fool&#39;s Gold：防不住就去骗——对抗「安全移除」的开源权重诱饵加固 <a class="header-anchor" href="#🛡️-fool-s-gold-防不住就去骗——对抗「安全移除」的开源权重诱饵加固" aria-label="Permalink to &quot;🛡️ Fool&#39;s Gold：防不住就去骗——对抗「安全移除」的开源权重诱饵加固&quot;">​</a></h3><p><strong>Fool&#39;s Gold: Defensive Deception Against Safety-Removal Attacks on Open-Weight Models</strong><em>arXiv (2026)</em></p><p>开源权重模型的安全对齐可被「abliteration」在几分钟内投影掉拒答方向，发布侧防御无一能持久阻止。Mark Russinovich 的方案是承认拒答会被剥离、转而毒化其收益：一旦拒答被剥，绝大多数危险操作性请求得到的是自信、流畅但<strong>关键要素被伪造</strong>的诱饵答案。诱饵在可微的攻击模拟内部训练，只在「被攻击态」表达；「拒答销 + 良性牵引」把干净态行为钉在原模型上。在 5 个家族 7 个模型（9B–122B，稠密与 MoE）上，通过预注册效力门槛的 6 个模型中，攻击态对留出提示的诱饵率为 0.51–0.90（其中 +0.27–0.84 可归因于防御），良性行为与能力预算均未超；第 7 个较小模型未过门槛。在外部红队 CBRNE 相邻切片上，受防御的 122B 在「同等质量」答案中有 0.82–0.86 是致命错误，未防御者至多 0.10；K=64 逐要素共识仍能在 0.083–0.625 的提示上重建可用流程（未防御 0.58–0.96），且无标签方法可区分两种情形。作者明确局限：不覆盖上下文内越狱，只保护最初发布的受防御权重。arXiv: <a href="https://arxiv.org/abs/2608.17202" target="_blank" rel="noreferrer">2608.17202</a></p><h3 id="🎯-qwm-把世界模型架在-q-learning-之上做测试时搜索" tabindex="-1">🎯 QWM：把世界模型架在 Q-learning 之上做测试时搜索 <a class="header-anchor" href="#🎯-qwm-把世界模型架在-q-learning-之上做测试时搜索" aria-label="Permalink to &quot;🎯 QWM：把世界模型架在 Q-learning 之上做测试时搜索&quot;">​</a></h3><p><strong>Q-Learning With World Models</strong><em>arXiv (2026)</em></p><p>离策略 RL 已足够省样本，可用于把 VLA 微调成可靠策略；世界模型能预测状态变化（而非只预测动作），却大多只在监督式策略学习里成功。此前的基于模型 RL 直接在「想象轨迹」上优化策略或价值函数，容易累积模型偏差，难以扩展到真实机器人这类高维长程问题。Perry Dong、Chelsea Finn、Dorsa Sadigh 等改问：能否把世界模型直接架在标准 Q-learning 上面？他们提出 QWM——策略与价值函数<strong>只在真实转移上训练</strong>，世界模型仅在测试时用来在想象轨迹上做搜索，为在线 rollout 与评测挑选高价值动作。这样既避免了模型偏差的复利，又保留了预测式搜索的样本效率。在 Robomimic 与 LIBERO 操作基准上，QWM 在样本效率与最终性能上均显著优于此前的强基线。arXiv: <a href="https://arxiv.org/abs/2608.17163" target="_blank" rel="noreferrer">2608.17163</a></p><h3 id="📊-case-一个「可解码性」指标-预先判断隐藏态选答何时能赢过多数投票" tabindex="-1">📊 CASE：一个「可解码性」指标，预先判断隐藏态选答何时能赢过多数投票 <a class="header-anchor" href="#📊-case-一个「可解码性」指标-预先判断隐藏态选答何时能赢过多数投票" aria-label="Permalink to &quot;📊 CASE：一个「可解码性」指标，预先判断隐藏态选答何时能赢过多数投票&quot;">​</a></h3><p><strong>A decodability criterion predicts when hidden-state selection beats majority voting in large language models</strong><em>arXiv (2026)</em></p><p>把 LLM 多次采样合成一个答案是测试时的信息融合问题，通常用多数投票；但难题上采样答案的错误彼此相关，错答案可能胜出，采得更多反而更差。从隐藏态读「正确性信号」再选候选是替代方案，但其跨模型、跨任务的可靠性无指标可判。作者提出 CASE（Correctness-Axis SElection）：在答案 token 的隐藏态上训练线性门控，选得分最高的候选；核心贡献是 <strong>decodability</strong>——一个无泄漏的度量，衡量门控把某题正确候选排到错误候选之上的能力，可预测「隐藏态选答」是否优于投票。常规探针看似准确，其实来自「题目身份泄漏」，按题分组评测即消失。留出数据上，decodability 与「选答相对投票的准确率增益」的 Pearson 相关 r = 0.75，决策阈值约在 AUC = 0.60；在通用与医学 LLM 上，CASE 相对投票在中等难度题最多 +19 点、困难题 +16.8 点。该指标取决于模型必须回忆的对齐知识而非规模，且可跨域迁移（未见科学域内误差 3.8 点内）。arXiv: <a href="https://arxiv.org/abs/2608.17124" target="_blank" rel="noreferrer">2608.17124</a></p><h3 id="🧑‍🏫-knowsim-用「会学习」的用户模拟器评-llm-的信息校准" tabindex="-1">🧑‍🏫 KnowSim：用「会学习」的用户模拟器评 LLM 的信息校准 <a class="header-anchor" href="#🧑‍🏫-knowsim-用「会学习」的用户模拟器评-llm-的信息校准" aria-label="Permalink to &quot;🧑‍🏫 KnowSim：用「会学习」的用户模拟器评 LLM 的信息校准&quot;">​</a></h3><p><strong>KnowSim: Evaluating Information Calibration in LLM Assistants with User Simulators that Learn</strong><em>arXiv (2026)</em></p><p>与用户协作完成知识密集任务，LLM 必须做<strong>信息校准</strong>：把内容匹配到用户不断演变的理解与认知容量。但现有用户模拟器不显式建模用户知识，既无法产生不同知识水平下的真实交互，也无法反映知识演变过程。KnowSim 把用户知识态写成一张带先修关系的信息单元图，按学习理论导出的更新规则演化，并直接从知识态轨迹算出三项指标：知识增益、交付校准、认知过载。作者用两个领域、按知识水平分层的 705 场真人—AI 会话验证：其排序与人类判断显著一致（符号一致率 73–74%），优于三个基线模拟器。用于评测 9 个 LLM 时发现，「最好的模型」会随用户知识水平而换人——这种能力—处理交互（aptitude-treatment interaction）在标准评测里完全不可见。arXiv: <a href="https://arxiv.org/abs/2608.17150" target="_blank" rel="noreferrer">2608.17150</a></p><blockquote><p>📅 日期：2026-08-17 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',35)])])}const p=a(n,[["render",i]]);export{m as __pageData,p as default};
